// Парсинг события + (опционально) проверка исходящего IP против белого списка ЮKassa.
//
// ЮKassa-белый список (на ноябрь 2024):
//   185.71.76.0/27, 185.71.77.0/27,
//   77.75.153.0/25, 77.75.154.128/25,
//   77.75.156.11, 77.75.156.35,
//   2a02:5180::/32
//
// STRICT_IP_CHECK=true заворачивает запросы с не-whitelist IP.
// На первом запуске оставь false: пока не настроишь reverse proxy + N8N_PROXY_HOPS,
// n8n будет видеть IP прокси, а не ЮKassa.
const STRICT_IP_CHECK = false;

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

function ipToLong(ip) {
  return ip.split('.').reduce((acc, oct) => (acc << 8) + Number(oct), 0) >>> 0;
}
function inCidr(ip, cidr) {
  if (!ip || ip.includes(':')) return false;
  const [range, bits] = cidr.split('/');
  const mask = bits === '32' ? 0xFFFFFFFF : (~0 << (32 - Number(bits))) >>> 0;
  return (ipToLong(ip) & mask) === (ipToLong(range) & mask);
}

const WHITELIST_V4 = [
  '185.71.76.0/27',
  '185.71.77.0/27',
  '77.75.153.0/25',
  '77.75.154.128/25',
  '77.75.156.11/32',
  '77.75.156.35/32'
];

const rawXff = headers['x-forwarded-for'] || headers['X-Forwarded-For'] || '';
const rawRealIp = headers['x-real-ip'] || headers['X-Real-IP'] || '';
const clientIp = (String(rawXff).split(',')[0] || String(rawRealIp) || '').trim();
const ipOk = clientIp && WHITELIST_V4.some((cidr) => inCidr(clientIp, cidr));

if (STRICT_IP_CHECK && !ipOk) {
  throw new Error('YooKassa notify: IP вне белого списка ЮKassa: ' + (clientIp || '(пустой)'));
}

const eventType = String(body.event || '');
const obj = body.object || {};
const paymentId = String(obj.id || '');
if (!paymentId) {
  throw new Error('YooKassa notify: в body.object.id пусто, нечего проверять');
}
if (!eventType.startsWith('payment.') && !eventType.startsWith('refund.')) {
  throw new Error('YooKassa notify: неизвестный event=' + eventType);
}

return [{
  json: {
    clientIp,
    ipOk,
    eventType,
    paymentId,
    bodyStatus: String(obj.status || ''),
    bodyMetadata: obj.metadata || {}
  }
}];

// Решаем что делать дальше:
//  - payment.succeeded + status === 'succeeded' → парсим metadata.plannerPayload и шлём в planner
//  - всё остальное (canceled, refunded, pending, неуспешные) → пропускаем тихо, return [] останавливает ветку
const parsed = $('Parse event & IP').first().json;
const api = $input.first().json;

const eventType = parsed.eventType;
const apiStatus = String(api.status || '');
const metadata = api.metadata || parsed.bodyMetadata || {};

if (eventType !== 'payment.succeeded' || apiStatus !== 'succeeded') {
  console.log('YooKassa notify: пропуск event=' + eventType + ', api.status=' + apiStatus + ', payment_id=' + parsed.paymentId);
  return [];
}

let planner;
try {
  planner = typeof metadata.plannerPayload === 'string'
    ? JSON.parse(metadata.plannerPayload)
    : metadata.plannerPayload;
} catch (e) {
  throw new Error('YooKassa notify: не смог распарсить metadata.plannerPayload: ' + String(e));
}
if (!planner || typeof planner !== 'object') {
  throw new Error('YooKassa notify: metadata.plannerPayload пуст или невалиден');
}

// Финальный payload для planner-webhook: гарантируем premium-тариф
const plannerPayload = {
  ...planner,
  tier: 'premium',
  email: String(planner.email || metadata.email || '').trim().toLowerCase(),
  source: 'yookassa',
  paymentId: parsed.paymentId
};

if (!plannerPayload.email || !plannerPayload.email.includes('@')) {
  throw new Error('YooKassa notify: некорректный email в metadata, payment_id=' + parsed.paymentId);
}

return [{ json: { plannerPayload, paymentId: parsed.paymentId } }];
